(106, 1, 'multiple', '高处作业监护人应充分了解作业的（），了解周边环境和风险', '["内容，地点（位号），时间", "作业要求", "作业步骤", "作业工具"]', '[0, 1]', '', '2026-05-30 11:24:23'),
(107, 1, 'multiple', '安全带应系挂在施工作业处上方的牢固构件上，不得系挂在有（）的部位', '["尖锐棱角", "有可能转动", "脚手架的横杆", "高处的生命绳"]', '[0, 1]', '', '2026-05-30 11:24:23'),
(108, 1, 'multiple', '脚手架（）过程中，作业区域未设置安全警戒区，监护不到位，地面行人随意穿梭警戒区等情况属于违章', '["搭设", "拆除", "改动", "脚手架验收"]', '[0, 1, 2]', '', '2026-05-30 11:24:23'),
(109, 1, 'multiple', '脚手架搭设过程中，监护员应督促施工人员严格执行《金陵石化作业安全管理实施细则》，严防交叉作业，确需交叉作业，应执行“（）”，防止物体打击事故。', '["错时", "错位", "硬隔离", "停止搭设"]', '[0, 1, 2]', '', '2026-05-30 11:24:23'),
(110, 1, 'multiple', '（）违反高处作业安全管理规定。', '["安全带应高挂（系）低用", "高处作业上下投掷工具、材料和杂物等", "在同一坠落方向上，中间无安全防护层，上下同时作业", "作业人员高处休息"]', '[1, 2, 3]', '', '2026-05-30 11:24:23'),
(111, 1, 'multiple', '高处作业所用的工具、零件、材料等必须装入工具袋，上下时（）,不准()，工作完毕应及时将工具、零星材料、零部件等一切易坠落物件清理收拾好，防止落下伤人', '["手中不得拿物件", "在高处投掷材料、工具或他物", "携带工具袋"]', '[0, 1]', '', '2026-05-30 11:24:23'),
(112, 1, 'multiple', '三催化装置丙烯塔高80m,在塔顶以下作业不需要开具高处作业票的作业活动有（）？', '["更换塔顶照明灯", "操作人员正常巡检", "设备人员检查塔顶放空阀是否内漏", "工艺人员检查塔顶放空阀是否安装了盲板"]', '[1, 2, 3]', '', '2026-05-30 11:24:23'),
(113, 1, 'multiple', '盲板抽（堵）作业时，在有毒有害、易燃易爆介质情况下操作时，（）等个人防护用品的违章行为属于违章。', '["佩戴便携式气体检测仪", "未使用防爆工具", "未佩戴便携式气体检测仪", "未佩戴空气呼吸器"]', '[1, 2, 3]', '', '2026-05-30 11:24:23'),
(114, 1, 'multiple', '双方监护人在抽（堵）盲板作业前，应进行检查，确保盲板位置正确，盲板图中（）应一一对应。', '["盲板编号", "具体位置", "盲板作业票", "盲板作业人员"]', '[0, 1]', '', '2026-05-30 11:24:23'),
(115, 1, 'multiple', '距盲板作业点30米内不得有（）等其它作业。', '["用火", "采样", "放空", "排放"]', '[0, 1, 2, 3]', '', '2026-05-30 11:24:23'),
(116, 1, 'multiple', '盲板作业人员应在（），在拆除螺栓时，应按对称、夹花拆除，拆除最后两条对称螺栓前应再次确认管道设备内无压力。', '["上风向作业", "不得正对法兰缝隙", "站在脚手架上作业", "不应佩带安全带"]', '[0, 1]', '', '2026-05-30 11:24:23'),
(117, 1, 'multiple', '机泵检修作业时，机泵机体内介质排放干净，（）；机体内吹扫置换干净', '["排空阀已打开", "排空阀畅通", "压力表回零", "地沟去含油地漏畅通"]', '[0, 1, 2]', '', '2026-05-30 11:24:23'),
(118, 1, 'multiple', '在（）或其他封闭、半封闭场所作业，属于受限空间作业', '["III催化装置的反应器内", "渣加的分馏塔内", "蜡加的加热炉炉膛内", "消防水阀门窨井内"]', '[0, 1, 2, 3]', '', '2026-05-30 11:24:23'),
(119, 1, 'truefalse', '《中华人民共和国长江保护法》中规定禁止在长江干支流岸线一公里范围内新建、扩建化工园区和化工项目。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(120, 1, 'truefalse', '实施雨污分流、清污分流的工业企业应当按照有关规定标识雨水管、清下水管、污水管的走向，在雨水、污水排放口或者接管口设置标识牌。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(121, 1, 'truefalse', '根据《金陵石化污染防治管理实施细则》，各单位明沟排水系统应无淤泥杂物、无泄漏物料、盖板无缺损、排水无漫溢无渗漏。界区雨排、污水排水口合理归并，提升泵、计量表、连通线、隔断阀等设施完好，标识完整、正确。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(122, 1, 'truefalse', '大雨中，各单位领导必须到现场检查、指挥管辖区内的清污分流工作。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(123, 1, 'truefalse', '废水排放浓度未发生变化，只是排水水量和排水去向发生变化不需要向安全环保部提报非常规排污申请，可按照工艺需要排放。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(124, 1, 'truefalse', '排污单位必须提前对需要排放的污水进行污染因子浓度测定，以便判断环境影响因数级别和确定排污控制措施。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(125, 1, 'truefalse', '装置检修时应合理安排冷凝液和不凝气的去向，确保废气达标排放和不发生扰民事件。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(126, 1, 'truefalse', '产生工业固体废物的单位应当向所在地生态环境主管部门提供工业固体废物的种类、数量、流向、贮存、利用、处置等有关资料。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(127, 1, 'truefalse', '从事危险废物收集、贮存、运输、利用和处置的人员，应接受专业培训。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(128, 1, 'truefalse', '任何单位和个人不得损毁、盗窃环境监测设施。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(129, 1, 'truefalse', '《中华人民共和国环境保护法》规定严禁通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行防治污染设施等逃避监管的方式违法排放污染物。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(130, 1, 'truefalse', '被淘汰的设备和产品，可以转让给他人使用。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(131, 1, 'truefalse', '环境影响是指全部或部分因公司环境因素给环境造成的不利影响。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(132, 1, 'truefalse', '不同类废物间存放时可以设置过道、隔离墙等明显的间隔。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(133, 1, 'truefalse', '收集、贮存危险废物设施、场所，必须同时设置危险废物的警告标志和标签。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(134, 1, 'truefalse', '贮存场所地面须作硬化处理，场所应有雨棚、围堰或围墙。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(135, 1, 'truefalse', '根据《江苏省工业企业安全生产风险报告规定》，企业应将各个风险单元的风险等级在厂区和车间平面布置图中用红、橙、黄、蓝 4 种颜色标示，形成安全风险四色分布图，在厂区醒目位置进行公示。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(136, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，采用新技术、新工艺、新设备和新材料时，如未到公司全年评估时间，可不进行风险评估。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(137, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，各运行部（工厂）根据生产实际需要，在现场设置重要操作的提示标志（如关键机组、特殊阀门的现场操作等）。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(138, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，公司HSE委员会下设安全环保、生产技术、设备电仪、教育培训、承包商、销售后勤专业分委员会，专业分委员会主任由公司业务分管领导担任。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(139, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，环保设施应先停后开，确保污染物受控及达标排放。停开工的环保信息应按要求向政府环保部门报备。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(140, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，生产准备工作应在项目中交前组织开展，各参建部门按职责分工，分阶段完成组织、人员、技术和物资等准备，落实相关HSE 方案和措施。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(141, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，新任基层领导干部及班组长，上岗后应通过安全环保培训及考核。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(142, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》,员工是HSE管理体系全员参与要素的实施主体。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(143, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，运行部（工厂）负责按操作规程投用储罐高液位报警及联锁，严禁超液位运行，落实防冒罐跑油措施。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(144, 1, 'truefalse', '依据《金陵石化HSE管理体系手册》，中石化集团公司规定职工参加体检率100%。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(145, 1, 'truefalse', '依据《金陵石化安全教育管理实施细则》，基层员工在岗安全培训不少于20学时/年，班组长不少于24学时/年。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(146, 1, 'truefalse', '依据《金陵石化安全教育管理实施细则》，生产一线岗位从业人员必须具有化工职业教育背景或普通高中及以上学历并接受危险化学品安全培训，经考核合格后方能上岗。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(147, 1, 'truefalse', '依据《金陵石化安全教育管理实施细则》，转岗、离岗9个月以上（含9个月）者实行二、三两级安全教育，经考核合格后，方可上岗。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(148, 1, 'truefalse', '依据《金陵石化工艺技术管理实施细则》，无论关键工艺参数的报警值还是联锁回路的报警值、联锁值操作人员都无权限更改。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(149, 1, 'truefalse', '依据《金陵石化设备润滑管理实施细则》，透平油、冷冻机油、全损耗系统油及粘度相近的油品一级滤网80目、二级滤网100目、三级滤网120目。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(150, 1, 'truefalse', '依据《金陵石化生产安全事故事件管理实施细则》，患职业病的情形,不属于工伤。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(151, 1, 'truefalse', '依据《金陵石化生产安全事故事件管理实施细则》，用人单位必须依法参加工伤保险。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(152, 1, 'truefalse', '依据《金陵石化生产安全事故事件管理实施细则》，在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的情形应当认定工伤。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(153, 1, 'truefalse', '依据《金陵石化突发环境事件风险管理及应急管理实施细则》,突发环境事件按照事件严重程度，分为特别重大、重大、较大和一般四级。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(154, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，“两特两重”指特殊地区、特殊时期、重大活动、重大节日。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(155, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，“五个回归”是一种问题溯源分析的方法。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(156, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，HSE管理体系手册只是HSE管理者必须遵循的准则。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(157, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，除硫化氢应急施救前需做好自身防护外，其他情况先救人。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(158, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，电气设备检维修必须先停电、后上锁挂牌。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(159, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，各级领导应鼓励员工主动报告事件和风险隐患等信息。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(160, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，工会应依规组织员工对 HSE 工作进行民主监督，维护员工合法权益。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(161, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，基层主要负责人对本单位 HSE 工作全面负责，基层专业技术人员承担专业安全环保管理职责。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(162, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，企业各级领导应经常深入一线与员工沟通，通过定点承包、开展安全观察等方式，及时掌握基层 HSE 动态。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(163, 1, 'truefalse', '依据《中国石油化工集团有限公司HSE管理体系手册》，企业应落实防冒罐跑油、防硫化亚铁自燃、防雷击等安全措施。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(164, 1, 'truefalse', '依照《中华人民共和国环境保护法》，排污单位通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行污染防治设施等逃避监管的方式违法排放污染物。对其直接负责的主管人员和其他直接责任人员处以拘留。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(165, 1, 'truefalse', '用火作业应全过程视频监控，因无法采取接火，施工人员可以擅自挪动遮盖视频监控设备，短时作业无需对作业过程进行跟踪拍摄。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(166, 1, 'truefalse', '由于生产任务重，所以班组可以按排一个新来的大学生监火，用火监护人无需了解用火区域或岗位的生产过程，熟悉工艺操作和设备状况。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(167, 1, 'truefalse', '双方用火监护人应在项目负责人的指导下，逐项检查落实防火措施。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(168, 1, 'truefalse', '某天，四部蜡加进行蒸汽动火消漏，用火人在没有完成地漏封堵前就开始动火，监护人劝阻后，施工人员仍然动火作业，监火人有权收回许可证，并向上级报告。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(169, 1, 'truefalse', '在冬天检修现场，为防止风吹，现场可用可燃的塑料布做防风布使用。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(170, 1, 'truefalse', '气瓶可以直接靠近放置在装置无保温材料蒸汽管道法兰边上。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(171, 1, 'truefalse', '地下埋地管线需要保温防腐，在现场熬沥青不属于动火作业。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(172, 1, 'truefalse', '在检修现场，为了节省时间，可以直接向受限空间内充净化风或非净化风。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(173, 1, 'truefalse', '在特殊情况下进入受限空间作业，作业人员可戴供风式面具，拴救生绳，使用供风式面具时，不必安排专人监护供风设备。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(174, 1, 'truefalse', '在检修现场，上午打开的人孔分析合格之后，因为下午要作业，所以不必用人孔封闭器进行封闭并挂严禁进入警示牌。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(175, 1, 'truefalse', '可以携带手机等常用通讯设备进入原来盛装易燃易爆介质的塔内作业。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(176, 1, 'truefalse', '受限空间作业是指进入受限空间内部进行的作业，探入受限空间不属于进入受限空间作业。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(177, 1, 'truefalse', '作业人员进入受限空间要佩戴便携式气体报警仪。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(178, 1, 'truefalse', '发生人员中毒、窒息的紧急情况，抢救人员必须佩戴隔离式防护面具进入受限空间，严禁无防护救援，并至少有 1 人在受限空间外部负责联络工作。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(179, 1, 'truefalse', '受限空间许可证中各栏目，分别由相应责任人填写，其他人不得代签；作业人员、监护人姓名应与许可证一致。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(180, 1, 'truefalse', '入塔器裙座内搭设脚手架，可以不开具受限空间作业许可证。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(181, 1, 'truefalse', '受限空间作业人员在安全措施不落实、作业监护人不在场等情况下有权拒绝作业，并向上级报告。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(182, 1, 'truefalse', '受限空间作业结束后，应对受限空间进行全面检查，清点人数和工具，确认无误后，施工单位和基层单位双方签字验收，人孔立即封闭。', '["对", "错"]', '0', '', '2026-05-30 11:24:23'),
(183, 1, 'truefalse', '受限空间作业期间，作业人员累了，在受限空间内休息。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(184, 1, 'truefalse', '由于蜡加地下罐入口管线的法兰无法涨开，施工人员就用使用白铁皮代替盲板。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
(185, 1, 'truefalse', '在抽(堵)液态烃泵出入口盲板时，施工单位由于没有铜锤，就用铁器敲打法兰和螺栓。', '["对", "错"]', '1', '', '2026-05-30 11:24:23'),
